-- Taiwan deep-dive ES/DE/FR translations (completing 342).
-- INSERT OR IGNORE throughout.

-- ==================== es ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'es', 'Transmisión electrónica posterior a la emisión a través de la Plataforma de Facturación Electrónica del Ministerio de Finanzas -- el eGUI es obligatorio para todas las entidades registradas a efectos del impuesto empresarial desde el 1 de enero de 2021', 'Esta página de análisis refleja la orientación pública del Ministerio de Finanzas y la información del sector disponible a principios de agosto de 2026, y se ofrece a título informativo general, no como asesoramiento legal o fiscal. Confirme los requisitos vigentes directamente en la Plataforma de Facturación Electrónica del Ministerio de Finanzas o con un asesor fiscal de Taiwán antes de basar en esta página sus decisiones de cumplimiento.', 'El sistema eGUI (Factura Uniforme Gubernamental electrónica) de Taiwán se construyó por etapas en lugar de aparecer de una sola vez. El registro de IVA transfronterizo y las obligaciones de eGUI para proveedores extranjeros de servicios digitales comenzaron el 1 de mayo de 2017. El mandato universal llegó después, el 1 de enero de 2021, exigiendo a toda entidad registrada a efectos del impuesto empresarial -- nacional y extranjera, B2B y B2C -- emitir eGUI en formato estructurado. Una enmienda a la Ley del Impuesto al Valor Agregado y No Valor Agregado (BTA), publicada el 3 de septiembre de 2024, formalizó después los plazos de transmisión (7 días para B2B, 2 días para B2C) y reforzó las sanciones. Más recientemente, el formato XML de la Guía de Implementación de Mensajes (MIG) 4.0, introducido el 1 de enero de 2024, se convirtió en el único formato eGUI válido una vez que el período de transición de los formatos MIG 3.1/3.2 finalizó el 31 de diciembre de 2025.', 'Un eGUI conforme debe emitirse en el formato XML MIG 4.0 vigente -- los formatos anteriores MIG 3.1/3.2 se retiraron el 31 de diciembre de 2025 y ya no se aceptan. Las facturas se transmiten a la Plataforma de Facturación Electrónica del Ministerio de Finanzas, operada junto con la Agencia de Información Fiscal (FIA).', 'El mandato cubre a toda entidad registrada a efectos del impuesto empresarial en Taiwán -- nacional y extranjera, B2B y B2C -- desde el 1 de enero de 2021. Los proveedores extranjeros de servicios digitales que venden a Taiwán están, por separado, dentro del ámbito del registro de IVA transfronterizo y la emisión de eGUI desde el 1 de mayo de 2017, una vez superan un umbral de registro. La adopción de Peppol como Autoridad en septiembre de 2025 añade una opción voluntaria de intercambio transfronterizo sobre el mandato doméstico existente; no cambia quién está obligado a emitir eGUI.', 'Prepararse significa confirmar que su sistema de facturación o ERP ya migró su salida de eGUI a MIG 4.0 (obligatorio desde el 1 de enero de 2026), incorporar en su flujo de trabajo los plazos de transmisión de 7 días (B2B) y 2 días (B2C), y -- si es proveedor extranjero de servicios digitales -- confirmar su estado de registro de IVA transfronterizo.', 'Taiwán respalda sus normas de facturación electrónica con multas bajo la Ley del Impuesto Empresarial enmendada: TWD 1.500-15.000 por transmisión tardía o faltante, con sanciones crecientes por infracciones repetidas, y exposición adicional por datos de factura transmitidos de forma inexacta.', 'El Ministerio de Finanzas de Taiwán opera el eGUI (Factura Uniforme Gubernamental electrónica) como un modelo de transmisión posterior a la emisión: una factura es válida en cuanto llega al comprador, y la transmisión a la Plataforma de Facturación Electrónica del MOF es una obligación aparte y con plazo, no una condición previa para su validez. El mandato se volvió universal el 1 de enero de 2021, cubriendo a toda entidad registrada a efectos del impuesto empresarial tanto para transacciones B2B como B2C. Una enmienda a la Ley del Impuesto Empresarial (publicada el 3 de septiembre de 2024) fijó plazos de transmisión de 7 días para facturas B2B y 2 días para facturas B2C, respaldados por multas de TWD 1.500-15.000. Desde el 1 de enero de 2026, el formato XML MIG 4.0 es el único formato eGUI válido -- los formatos MIG 3.1/3.2 ya no son aptos. En septiembre de 2025, Taiwán se convirtió además en una Autoridad Peppol, una iniciativa voluntaria para estandarizar la facturación transfronteriza con miembros de la red que incluyen Australia, Japón, Malasia, Nueva Zelanda, Singapur y el Reino Unido.', '🇹🇼' FROM countries WHERE name_en = 'Taiwan';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '1 ene 2021', 'eGUI obligatorio para todas las entidades registradas a efectos del impuesto empresarial' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Taiwan' AND s.sort_order = 0;
