INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', 'TWD 1.500-15.000', 'Rango de multas por transmisión tardía o inexacta' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Taiwan' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', 'MIG 4.0', 'Único formato eGUI válido desde el 1 de enero de 2026' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Taiwan' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '1 may 2017', 'Comienza el régimen de IVA/eGUI transfronterizo para proveedores digitales extranjeros' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Taiwan' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Formato y estándar', '[["Formato", "XML de la Guía de Implementación de Mensajes (MIG) 4.0 -- el único formato eGUI válido desde el 1 de enero de 2026"], ["Formato heredado", "MIG 3.1/3.2, permitido durante un período de transición hasta el 31 de diciembre de 2025, ahora retirado"], ["Plataforma de reporte", "Plataforma de Facturación Electrónica del Ministerio de Finanzas, operada con la Agencia de Información Fiscal (FIA)"], ["Base legal", "Ley del Impuesto al Valor Agregado y No Valor Agregado (BTA), enmendada el 7 de agosto de 2024 / publicada el 3 de septiembre de 2024"]]', 'Confirme que la salida eGUI de su sistema de facturación o ERP ha completado la migración a MIG 4.0 -- las presentaciones en MIG 3.1/3.2 se rechazan de forma directa desde el 1 de enero de 2026.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Taiwan' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Identificadores y registro', '[["Registro empresarial", "Número Uniforme de Empresa de Taiwán, registrado a efectos del impuesto empresarial"], ["Vía de registro", "Plataforma de Facturación Electrónica del Ministerio de Finanzas, o un socio de facturación/software certificado"], ["Proveedores digitales extranjeros", "Se registran bajo el régimen de IVA de servicios electrónicos transfronterizos una vez superado el umbral de registro"], ["Organismos responsables", "Ministerio de Finanzas (MOF) y Agencia de Información Fiscal (FIA)"]]', 'Las empresas extranjeras sin presencia en Taiwán deben confirmar que su agente local o socio de facturación certificado está registrado y presenta declaraciones en su nombre.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Taiwan' AND cd.section = 'file_format' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Contenido obligatorio', '[["Formato estructurado requerido", "XML MIG 4.0 -- los PDF y otros formatos no estructurados no califican como eGUI válidos"], ["Campos principales", "Identificadores de emisor/comprador, secuencia numérica de la factura, detalle de venta desglosado, importe del IVA"], ["Plazo", "Debe transmitirse dentro de 7 días (B2B) o 2 días (B2C) desde la emisión"], ["Conservación", "Se aplican las reglas estándar de conservación contable de Taiwán -- confirme el período vigente con un asesor fiscal"]]', 'El requisito de plazo de transmisión se suma al requisito de formato -- un eGUI con formato correcto pero transmitido tarde sigue siendo un incumplimiento.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Taiwan' AND cd.section = 'file_format' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'es', 'El flujo de emisión y luego transmisión', 'Un eGUI de Taiwán recorre esta secuencia -- observe que se trata de reporte posterior a la emisión, no de aclaración en tiempo real:', 'La factura ya es legalmente válida en cuanto llega al comprador -- no se solicita la aprobación previa del MOF, a diferencia de los mandatos de modelo de aclaración cubiertos en otras partes de este seguimiento (Colombia, Argentina, Jordania).' FROM deep_dive_lifecycle_cards lc JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Taiwan';
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'es', 'eGUI emitido al comprador en formato estructurado MIG 4.0' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Taiwan' AND st.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'es', 'Válido de forma inmediata -- no requiere aprobación previa del MOF' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Taiwan' AND st.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'es', 'Transmitido a la Plataforma del MOF dentro de 7 días (B2B) o 2 días (B2C)' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Taiwan' AND st.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'es', 'El MOF cruza las facturas transmitidas con las declaraciones de IVA presentadas' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Taiwan' AND st.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Quién está incluido, y desde cuándo', '[["Entidades nacionales registradas a efectos del impuesto empresarial", "Cubiertas desde el 1 de enero de 2021, B2B y B2C"], ["Proveedores extranjeros de servicios digitales (sobre el umbral)", "Cubiertos para IVA/eGUI transfronterizo desde el 1 de mayo de 2017"], ["Vendedores transfronterizos vía Peppol", "Voluntario desde el 22 de septiembre de 2025 -- no es un requisito obligatorio"]]', 'La adopción de Peppol como Autoridad en 2025 es explícitamente voluntaria -- añade una opción de intercambio internacional junto al mandato doméstico en lugar de sustituirlo o ampliar quién debe cumplir.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Taiwan' AND cd.section = 'scope_transmission' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Contexto transfronterizo: adopción de Peppol', '[["Autoridad", "Agencia de Industria Digital (bajo el Ministerio de Asuntos Digitales)"], ["Adoptado", "22 de septiembre de 2025"], ["Estado", "Voluntario -- las especificaciones Peppol localizadas siguen en desarrollo"], ["Miembros de la red mencionados", "Australia, Japón, Malasia, Nueva Zelanda, Singapur, Reino Unido"]]', 'Los seis miembros de la red Peppol mencionados son jurisdicciones seguidas por separado en este seguimiento de cumplimiento -- vale la pena revisarlo si ya intercambia facturas electrónicas con alguno de ellos.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Taiwan' AND cd.section = 'scope_transmission' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '💰 TWD 1.500-15.000 por transmisión tardía o inexacta', NULL, NULL, 'La enmienda a la Ley del Impuesto Empresarial publicada el 3 de septiembre de 2024 fijó multas de TWD 1.500-15.000 por incumplir el plazo de transmisión de 7 días (B2B) o 2 días (B2C), o por transmitir datos de factura inexactos. Las sanciones se agravan en caso de infracciones repetidas.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Taiwan' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '📅 Un mandato construido por etapas', NULL, NULL, 'La historia del eGUI en Taiwán avanzó en cuatro pasos distintos: obligaciones de IVA/eGUI transfronterizo para proveedores digitales extranjeros desde 2017, el mandato doméstico universal desde 2021, plazos de transmisión y sanciones más estrictas a partir de la enmienda BTA de 2024, y el MIG 4.0 convirtiéndose en el único formato válido desde 2026. Cada paso cambió una parte distinta de la obligación -- primero quién está cubierto, luego con qué rapidez, después en qué formato -- en lugar de una única fecha de mandato.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Taiwan' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '🌐 Transfronterizo: Peppol se suma, no es un nuevo mandato', NULL, NULL, 'La adopción de Peppol como Autoridad por parte de Taiwán en septiembre de 2025 es una iniciativa transfronteriza voluntaria supervisada por la Agencia de Industria Digital -- no modifica las obligaciones domésticas de eGUI ni introduce un nuevo plazo de cumplimiento. Trátela como una opción emergente para el comercio con otros miembros de la red Peppol (Australia, Japón, Malasia, Nueva Zelanda, Singapur, Reino Unido), no como un requisito.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Taiwan' AND cd.section = 'penalties_related' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'es', 'Transmisión tardía o faltante de un eGUI B2B (más de 7 días)', 'TWD 1.500-15.000', 'Se agrava con infracciones repetidas' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Taiwan' AND pr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'es', 'Transmisión tardía o faltante de un eGUI B2C (más de 2 días)', 'TWD 1.500-15.000', 'Se agrava con infracciones repetidas' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Taiwan' AND pr.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'es', 'Datos de factura transmitidos inexactos o erróneos', 'TWD 1.500-15.000', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Taiwan' AND pr.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Confirme que está cubierto -- prácticamente toda entidad registrada a efectos del impuesto empresarial lo está', 'Las entidades nacionales B2B y B2C están cubiertas desde el 1 de enero de 2021; no existe una excepción para pequeñas empresas como en otros mandatos.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Taiwan' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Confirme que su salida eGUI ha migrado a MIG 4.0', 'Las presentaciones en MIG 3.1/3.2 se rechazan de forma directa desde el 1 de enero de 2026 -- si su sistema de facturación o ERP no se ha actualizado, las transmisiones fallarán.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Taiwan' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Incorpore el plazo de 7 días / 2 días a su flujo de trabajo', 'Los eGUI B2B deben llegar a la plataforma del MOF dentro de 7 días desde la emisión, los B2C dentro de 2 días -- trátelos como plazos estrictos con multas asociadas, no como objetivos flexibles.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Taiwan' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Proveedores extranjeros de servicios digitales: confirmen su registro de IVA transfronterizo', 'Si vende servicios digitales a Taiwán por encima del umbral de registro, confirme que su registro de IVA y sus obligaciones de emisión de eGUI están al día -- esta vía se aplica desde 2017, aparte del mandato doméstico de 2021.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Taiwan' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Siga de cerca los desarrollos de Peppol si comercia con otros miembros de la red', 'La adopción de Peppol como Autoridad por Taiwán en septiembre de 2025 es voluntaria hoy, pero vale la pena seguirla si ya intercambia facturas electrónicas con Australia, Japón, Malasia, Nueva Zelanda, Singapur o el Reino Unido.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Taiwan' AND sp.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'es', 'Ministerio de Finanzas -- Plataforma de Facturación Electrónica' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.name_en = 'Taiwan' AND pt.sort_order = 0;

-- ==================== de ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'de', 'Elektronische Übermittlung nach Rechnungsausstellung über die E-Invoice-Plattform des Finanzministeriums -- eGUI ist für alle umsatzsteuerlich registrierten Unternehmen seit dem 1. Januar 2021 verpflichtend', 'Diese Analyseseite spiegelt öffentlich verfügbare Hinweise des Finanzministeriums und Brancheninformationen mit Stand Anfang August 2026 wider und dient allgemeinen Informationszwecken, nicht als Rechts- oder Steuerberatung. Bestätigen Sie aktuelle Anforderungen direkt auf der E-Invoice-Plattform des Finanzministeriums oder bei einem taiwanischen Steuerberater, bevor Sie sich bei Compliance-Entscheidungen auf diese Seite verlassen.', 'Taiwans eGUI-System (elektronische Government Uniform Invoice) entstand stufenweise und nicht auf einmal. Die grenzüberschreitende USt-Registrierung und eGUI-Pflichten für ausländische Anbieter digitaler Dienstleistungen begannen am 1. Mai 2017. Das universelle Mandat folgte am 1. Januar 2021 und verpflichtete jedes umsatzsteuerlich registrierte Unternehmen -- inländisch und ausländisch, B2B und B2C -- zur Ausstellung von eGUI im strukturierten Format. Eine am 3. September 2024 veröffentlichte Änderung des Umsatzsteuergesetzes (BTA) formalisierte anschließend Übermittlungsfristen (7 Tage für B2B, 2 Tage für B2C) und verschärfte die Sanktionen. Zuletzt wurde das XML-Format der Message Implementation Guideline (MIG) 4.0, eingeführt am 1. Januar 2024, zum einzig gültigen eGUI-Format, nachdem die Übergangsphase für die älteren Formate MIG 3.1/3.2 am 31. Dezember 2025 endete.', 'Ein konformes eGUI muss im aktuellen MIG-4.0-XML-Format ausgestellt werden -- die älteren Formate MIG 3.1/3.2 wurden am 31. Dezember 2025 abgeschafft und werden nicht mehr akzeptiert. Rechnungen werden an die E-Invoice-Plattform des Finanzministeriums übermittelt, die gemeinsam mit der Fiscal Information Agency (FIA) betrieben wird.', 'Das Mandat gilt für jedes umsatzsteuerlich registrierte Unternehmen in Taiwan -- inländisch und ausländisch, B2B und B2C -- seit dem 1. Januar 2021. Ausländische Anbieter digitaler Dienstleistungen, die nach Taiwan verkaufen, fallen separat seit dem 1. Mai 2017 unter die grenzüberschreitende USt-Registrierung und eGUI-Ausstellungspflicht, sobald sie eine Registrierungsschwelle überschreiten. Die Peppol-Authority-Übernahme im September 2025 fügt dem bestehenden inländischen Mandat eine freiwillige grenzüberschreitende Austauschoption hinzu; sie ändert nicht, wer zur Ausstellung von eGUI verpflichtet ist.', 'Zur Vorbereitung gehört, zu prüfen, ob die eGUI-Ausgabe Ihres Rechnungs- oder ERP-Systems bereits auf MIG 4.0 umgestellt wurde (verpflichtend seit 1. Januar 2026), die Übermittlungsfristen von 7 Tagen (B2B) und 2 Tagen (B2C) in Ihren Arbeitsablauf einzubauen und -- als ausländischer Anbieter digitaler Dienstleistungen -- Ihren grenzüberschreitenden USt-Registrierungsstatus zu bestätigen.', 'Taiwan untermauert seine E-Invoicing-Vorschriften mit Bußgeldern nach dem geänderten Umsatzsteuergesetz: TWD 1.500-15.000 für verspätete oder fehlende Übermittlung, mit steigenden Sanktionen bei wiederholten Verstößen, und zusätzlichem Risiko für ungenau übermittelte Rechnungsdaten.', 'Taiwans Finanzministerium betreibt eGUI (elektronische Government Uniform Invoice) als Übermittlungsmodell nach Rechnungsausstellung: Eine Rechnung ist gültig, sobald sie den Käufer erreicht, während die Übermittlung an die E-Invoice-Plattform des MOF eine separate, fristgebundene Pflicht ist, keine Voraussetzung für die Gültigkeit. Das Mandat wurde am 1. Januar 2021 universell und erfasst seither jedes umsatzsteuerlich registrierte Unternehmen sowohl für B2B- als auch B2C-Transaktionen. Eine Änderung des Umsatzsteuergesetzes (veröffentlicht am 3. September 2024) legte Übermittlungsfristen von 7 Tagen für B2B-Rechnungen und 2 Tagen für B2C-Rechnungen fest, unterlegt mit Bußgeldern von TWD 1.500-15.000. Seit dem 1. Januar 2026 ist das MIG-4.0-XML-Format das einzig gültige eGUI-Format -- die Formate MIG 3.1/3.2 sind nicht mehr zulässig. Im September 2025 wurde Taiwan zudem eine Peppol Authority, eine freiwillige Initiative zur Standardisierung der grenzüberschreitenden Rechnungsstellung mit Netzwerkmitgliedern wie Australien, Japan, Malaysia, Neuseeland, Singapur und dem Vereinigten Königreich.', '🇹🇼' FROM countries WHERE name_en = 'Taiwan';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '1. Jan. 2021', 'eGUI verpflichtend für alle umsatzsteuerlich registrierten Unternehmen' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Taiwan' AND s.sort_order = 0;
