INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Format & Standard', '[["Format", "Message Implementation Guideline (MIG) 4.0 XML -- das einzig gültige eGUI-Format seit 1. Januar 2026"], ["Altformat", "MIG 3.1/3.2, während einer Übergangsphase bis 31. Dezember 2025 zulässig, jetzt abgeschafft"], ["Meldeplattform", "E-Invoice-Plattform des Finanzministeriums, betrieben mit der Fiscal Information Agency (FIA)"], ["Rechtsgrundlage", "Umsatzsteuergesetz (BTA), geändert am 7. August 2024 / veröffentlicht am 3. September 2024"]]', 'Prüfen Sie, ob die eGUI-Ausgabe Ihres Rechnungs- oder ERP-Systems die Umstellung auf MIG 4.0 abgeschlossen hat -- Einreichungen im Format MIG 3.1/3.2 werden seit 1. Januar 2026 unmittelbar abgelehnt.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Taiwan' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Kennungen & Registrierung', '[["Unternehmensregistrierung", "Taiwanesische Uniform Business Number, umsatzsteuerlich registriert"], ["Registrierungsweg", "E-Invoice-Plattform des Finanzministeriums oder ein zertifizierter Rechnungs-/Softwarepartner"], ["Ausländische digitale Anbieter", "Registrierung im Rahmen der grenzüberschreitenden USt-Regelung für elektronische Dienstleistungen nach Überschreiten der Registrierungsschwelle"], ["Zuständige Behörden", "Finanzministerium (MOF) und Fiscal Information Agency (FIA)"]]', 'Ausländische Unternehmen ohne Präsenz in Taiwan sollten prüfen, ob ihr lokaler Vertreter oder zertifizierter Rechnungsdienstleister registriert ist und für sie Meldungen einreicht.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Taiwan' AND cd.section = 'file_format' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Pflichtinhalt', '[["Strukturiertes Format erforderlich", "MIG 4.0 XML -- PDFs und andere unstrukturierte Formate gelten nicht als gültige eGUI"], ["Kernfelder", "Aussteller-/Käuferkennungen, Rechnungsnummernfolge, aufgeschlüsselte Verkaufsdetails, USt-Betrag"], ["Zeitrahmen", "Muss innerhalb von 7 Tagen (B2B) oder 2 Tagen (B2C) nach Ausstellung übermittelt werden"], ["Aufbewahrung", "Es gelten die üblichen taiwanischen Aufbewahrungsvorschriften -- aktuelle Frist mit einem Steuerberater klären"]]', 'Die Frist zur Übermittlung kommt zusätzlich zur Formatanforderung hinzu -- ein korrekt formatiertes, aber verspätet übermitteltes eGUI bleibt ein Verstoß.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Taiwan' AND cd.section = 'file_format' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'de', 'Der Ablauf: erst ausstellen, dann übermitteln', 'Ein taiwanisches eGUI durchläuft diese Abfolge -- beachten Sie, dass es sich um eine Meldung nach Ausstellung handelt, nicht um eine Echtzeit-Freigabe:', 'Die Rechnung ist bereits rechtsgültig, sobald sie den Käufer erreicht -- das MOF muss sie nicht vorher genehmigen, anders als bei den an anderer Stelle in diesem Tracker erfassten Freigabemodellen (Kolumbien, Argentinien, Jordanien).' FROM deep_dive_lifecycle_cards lc JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Taiwan';
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'de', 'eGUI im strukturierten MIG-4.0-Format an den Käufer ausgestellt' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Taiwan' AND st.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'de', 'Sofort rechtsgültig -- keine vorherige Genehmigung des MOF erforderlich' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Taiwan' AND st.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'de', 'Übermittlung an die MOF-Plattform innerhalb von 7 Tagen (B2B) oder 2 Tagen (B2C)' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Taiwan' AND st.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'de', 'MOF gleicht übermittelte Rechnungen mit eingereichten USt-Erklärungen ab' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Taiwan' AND st.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Wer ist erfasst, und seit wann', '[["Inländische umsatzsteuerlich registrierte Unternehmen", "Erfasst seit 1. Januar 2021, B2B und B2C"], ["Ausländische Anbieter digitaler Dienstleistungen (über der Schwelle)", "Erfasst für grenzüberschreitende USt/eGUI seit 1. Mai 2017"], ["Grenzüberschreitende Anbieter über Peppol", "Freiwillig seit 22. September 2025 -- keine verpflichtende Anforderung"]]', 'Die Übernahme der Peppol Authority 2025 ist ausdrücklich freiwillig -- sie ergänzt das inländische Mandat um eine internationale Austauschoption, ohne den Kreis der Verpflichteten zu ersetzen oder zu erweitern.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Taiwan' AND cd.section = 'scope_transmission' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Grenzüberschreitender Kontext: Peppol-Übernahme', '[["Behörde", "Digital Industry Agency (unter dem Ministerium für digitale Angelegenheiten)"], ["Übernommen", "22. September 2025"], ["Status", "Freiwillig -- lokalisierte Peppol-Spezifikationen befinden sich noch in der Entwicklung"], ["Genannte Netzwerkmitglieder", "Australien, Japan, Malaysia, Neuseeland, Singapur, Vereinigtes Königreich"]]', 'Alle sechs genannten Peppol-Netzwerkmitglieder sind eigenständig erfasste Länder in diesem Compliance-Tracker -- es lohnt sich zu prüfen, ob Sie bereits mit einem davon E-Rechnungen austauschen.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Taiwan' AND cd.section = 'scope_transmission' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '💰 TWD 1.500-15.000 für verspätete oder ungenaue Übermittlung', NULL, NULL, 'Die am 3. September 2024 veröffentlichte Änderung des Umsatzsteuergesetzes legte Bußgelder von TWD 1.500-15.000 für das Verpassen der 7-Tage-Frist (B2B) oder 2-Tage-Frist (B2C) sowie für die Übermittlung ungenauer Rechnungsdaten fest. Die Sanktionen steigen bei wiederholten Verstößen.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Taiwan' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '📅 Ein Mandat, das schrittweise aufgebaut wurde', NULL, NULL, 'Die Geschichte des taiwanischen eGUI verlief in vier klaren Schritten: grenzüberschreitende USt-/eGUI-Pflichten für ausländische digitale Anbieter ab 2017, das universelle inländische Mandat ab 2021, Übermittlungsfristen und strengere Sanktionen durch die BTA-Änderung von 2024, und MIG 4.0 als einzig gültiges Format ab 2026. Jeder Schritt veränderte einen anderen Teil der Pflicht -- zuerst wer erfasst ist, dann wie schnell, dann in welchem Format -- statt eines einzigen Mandatsdatums.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Taiwan' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '🌐 Grenzüberschreitend: Peppol kommt hinzu, ist kein neues Mandat', NULL, NULL, 'Taiwans Übernahme der Peppol Authority im September 2025 ist eine freiwillige grenzüberschreitende Initiative unter Aufsicht der Digital Industry Agency -- sie ändert nicht die inländischen eGUI-Pflichten und führt keine neue Compliance-Frist ein. Betrachten Sie sie als aufkommende Option für den Handel mit anderen Peppol-Netzwerkmitgliedern (Australien, Japan, Malaysia, Neuseeland, Singapur, Vereinigtes Königreich), nicht als Anforderung.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Taiwan' AND cd.section = 'penalties_related' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'de', 'Verspätete oder fehlende Übermittlung eines B2B-eGUI (über 7 Tage)', 'TWD 1.500-15.000', 'Steigt bei wiederholten Verstößen' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Taiwan' AND pr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'de', 'Verspätete oder fehlende Übermittlung eines B2C-eGUI (über 2 Tage)', 'TWD 1.500-15.000', 'Steigt bei wiederholten Verstößen' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Taiwan' AND pr.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'de', 'Ungenaue oder fehlerhafte übermittelte Rechnungsdaten', 'TWD 1.500-15.000', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Taiwan' AND pr.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Prüfen Sie, ob Sie erfasst sind -- praktisch jedes umsatzsteuerlich registrierte Unternehmen ist es', 'Inländische B2B- und B2C-Unternehmen sind seit 1. Januar 2021 erfasst; es gibt keine Ausnahme für Kleinunternehmen wie bei manchen anderen Mandaten.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Taiwan' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Bestätigen Sie, dass Ihre eGUI-Ausgabe auf MIG 4.0 umgestellt wurde', 'Einreichungen im Format MIG 3.1/3.2 werden seit 1. Januar 2026 unmittelbar abgelehnt -- wurde Ihr Rechnungs- oder ERP-System nicht aktualisiert, schlagen Übermittlungen fehl.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Taiwan' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Bauen Sie die 7-Tage-/2-Tage-Übermittlungsfrist in Ihren Arbeitsablauf ein', 'B2B-eGUI müssen innerhalb von 7 Tagen nach Ausstellung die MOF-Plattform erreichen, B2C innerhalb von 2 Tagen -- behandeln Sie dies als feste Fristen mit Bußgeldfolge, nicht als weiche Ziele.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Taiwan' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Ausländische Anbieter digitaler Dienstleistungen: bestätigen Sie Ihre grenzüberschreitende USt-Registrierung', 'Wenn Sie digitale Dienstleistungen über der Registrierungsschwelle nach Taiwan verkaufen, bestätigen Sie, dass Ihre USt-Registrierung und eGUI-Ausstellungspflichten aktuell sind -- dieser Pfad gilt bereits seit 2017, getrennt vom inländischen Mandat von 2021.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Taiwan' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Beobachten Sie Peppol-Entwicklungen, wenn Sie mit anderen Netzwerkmitgliedern handeln', 'Taiwans Übernahme der Peppol Authority im September 2025 ist derzeit freiwillig, aber beobachtenswert, wenn Sie bereits mit Australien, Japan, Malaysia, Neuseeland, Singapur oder dem Vereinigten Königreich E-Rechnungen austauschen.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Taiwan' AND sp.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'de', 'Finanzministerium -- E-Invoice-Plattform' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.name_en = 'Taiwan' AND pt.sort_order = 0;

-- ==================== fr ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'fr', 'Transmission électronique postérieure à l''émission via la plateforme de facturation électronique du ministère des Finances -- l''eGUI est obligatoire pour toutes les entités enregistrées à la taxe professionnelle depuis le 1er janvier 2021', 'Cette page d''analyse reflète les orientations publiques du ministère des Finances et les informations du secteur disponibles début août 2026, et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Vérifiez les exigences actuelles directement sur la plateforme de facturation électronique du ministère des Finances ou auprès d''un conseiller fiscal taïwanais avant de fonder vos décisions de conformité sur cette page.', 'Le système eGUI (Facture Uniforme Gouvernementale électronique) de Taïwan s''est construit par étapes plutôt que d''un seul coup. L''enregistrement à la TVA transfrontalière et les obligations d''eGUI pour les fournisseurs étrangers de services numériques ont débuté le 1er mai 2017. Le mandat universel a suivi le 1er janvier 2021, exigeant que chaque entité enregistrée à la taxe professionnelle -- nationale et étrangère, B2B et B2C -- émette des eGUI au format structuré. Un amendement à la loi sur la taxe sur la valeur ajoutée et non-valeur ajoutée (BTA), publié le 3 septembre 2024, a ensuite formalisé les délais de transmission (7 jours pour le B2B, 2 jours pour le B2C) et renforcé les sanctions. Plus récemment, le format XML du Message Implementation Guideline (MIG) 4.0, introduit le 1er janvier 2024, est devenu le seul format eGUI valide une fois close la période de transition des anciens formats MIG 3.1/3.2, le 31 décembre 2025.', 'Un eGUI conforme doit être émis dans le format XML MIG 4.0 actuel -- les anciens formats MIG 3.1/3.2 ont été retirés le 31 décembre 2025 et ne sont plus acceptés. Les factures sont transmises à la plateforme de facturation électronique du ministère des Finances, exploitée avec la Fiscal Information Agency (FIA).', 'Le mandat couvre toute entité enregistrée à la taxe professionnelle à Taïwan -- nationale et étrangère, B2B et B2C -- depuis le 1er janvier 2021. Les fournisseurs étrangers de services numériques vendant vers Taïwan relèvent séparément de l''enregistrement à la TVA transfrontalière et de l''émission d''eGUI depuis le 1er mai 2017, une fois un seuil d''enregistrement dépassé. L''adoption du statut d''Autorité Peppol en septembre 2025 ajoute une option d''échange transfrontalier volontaire au mandat national existant ; elle ne modifie pas le périmètre des entités tenues d''émettre des eGUI.', 'Se préparer signifie vérifier que la sortie eGUI de votre système de facturation ou ERP a déjà migré vers le MIG 4.0 (obligatoire depuis le 1er janvier 2026), intégrer dans votre flux de travail les délais de transmission de 7 jours (B2B) et 2 jours (B2C), et -- si vous êtes fournisseur étranger de services numériques -- vérifier votre statut d''enregistrement à la TVA transfrontalière.', 'Taïwan appuie ses règles de facturation électronique sur des amendes prévues par la loi sur la taxe professionnelle modifiée : de 1 500 à 15 000 TWD pour transmission tardive ou manquante, avec des sanctions croissantes en cas de récidive, et une exposition distincte pour des données de facture transmises de façon inexacte.', 'Le ministère des Finances de Taïwan exploite l''eGUI (Facture Uniforme Gouvernementale électronique) selon un modèle de transmission postérieure à l''émission : une facture est valide dès qu''elle parvient à l''acheteur, la transmission à la plateforme de facturation électronique du MOF constituant une obligation distincte et soumise à délai, non une condition préalable à sa validité. Le mandat est devenu universel le 1er janvier 2021, couvrant toute entité enregistrée à la taxe professionnelle pour les transactions B2B comme B2C. Un amendement à la loi sur la taxe professionnelle (publié le 3 septembre 2024) a fixé des délais de transmission de 7 jours pour les factures B2B et de 2 jours pour les factures B2C, appuyés par des amendes de 1 500 à 15 000 TWD. Depuis le 1er janvier 2026, le format XML MIG 4.0 est le seul format eGUI valide -- les formats MIG 3.1/3.2 ne sont plus acceptés. En septembre 2025, Taïwan est également devenue une Autorité Peppol, une initiative volontaire visant à normaliser la facturation transfrontalière avec des membres du réseau tels que l''Australie, le Japon, la Malaisie, la Nouvelle-Zélande, Singapour et le Royaume-Uni.', '🇹🇼' FROM countries WHERE name_en = 'Taiwan';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '1er janv. 2021', 'eGUI obligatoire pour toutes les entités enregistrées à la taxe professionnelle' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Taiwan' AND s.sort_order = 0;
