INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '1er mai 2017', 'Début du régime de TVA/eGUI transfrontalier pour les fournisseurs numériques étrangers' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Taiwan' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Format et norme', '[["Format", "XML du Message Implementation Guideline (MIG) 4.0 -- le seul format eGUI valide depuis le 1er janvier 2026"], ["Format existant", "MIG 3.1/3.2, autorisé pendant une période de transition jusqu''au 31 décembre 2025, désormais retiré"], ["Plateforme de déclaration", "Plateforme de facturation électronique du ministère des Finances, exploitée avec la Fiscal Information Agency (FIA)"], ["Base légale", "Loi sur la taxe professionnelle (BTA), modifiée le 7 août 2024 / publiée le 3 septembre 2024"]]', 'Vérifiez que la sortie eGUI de votre système de facturation ou ERP a achevé la migration vers le MIG 4.0 -- les soumissions au format MIG 3.1/3.2 sont rejetées d''emblée depuis le 1er janvier 2026.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Taiwan' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Identifiants et enregistrement', '[["Enregistrement de l''entreprise", "Numéro d''entreprise uniforme taïwanais, enregistré à la taxe professionnelle"], ["Voie d''enregistrement", "Plateforme de facturation électronique du ministère des Finances, ou un prestataire de facturation/logiciel certifié"], ["Fournisseurs numériques étrangers", "S''enregistrent au titre du régime de TVA sur les services électroniques transfrontaliers une fois le seuil d''enregistrement dépassé"], ["Organismes compétents", "Ministère des Finances (MOF) et Fiscal Information Agency (FIA)"]]', 'Les entreprises étrangères sans présence à Taïwan doivent vérifier que leur agent local ou prestataire de facturation certifié est enregistré et déclare en leur nom.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Taiwan' AND cd.section = 'file_format' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Contenu obligatoire', '[["Format structuré requis", "XML MIG 4.0 -- les PDF et autres formats non structurés ne sont pas des eGUI valides"], ["Champs essentiels", "Identifiants émetteur/acheteur, séquence de numérotation de la facture, détail des ventes par poste, montant de la TVA"], ["Délai", "Doit être transmis dans un délai de 7 jours (B2B) ou 2 jours (B2C) après émission"], ["Conservation", "Les règles standards de conservation comptable taïwanaises s''appliquent -- vérifiez la durée actuelle avec un conseiller fiscal"]]', 'L''exigence de délai de transmission s''ajoute à l''exigence de format -- un eGUI correctement formaté mais transmis en retard reste un manquement.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Taiwan' AND cd.section = 'file_format' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'fr', 'Le flux : émettre, puis transmettre', 'Un eGUI taïwanais suit cette séquence -- notez qu''il s''agit d''une déclaration postérieure à l''émission, pas d''une validation en temps réel :', 'La facture est déjà juridiquement valide dès qu''elle parvient à l''acheteur -- le MOF n''est pas sollicité pour l''approuver au préalable, contrairement aux modèles de validation couverts ailleurs dans ce suivi (Colombie, Argentine, Jordanie).' FROM deep_dive_lifecycle_cards lc JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Taiwan';
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'fr', 'eGUI émis à l''acheteur au format structuré MIG 4.0' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Taiwan' AND st.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'fr', 'Valide immédiatement -- aucune approbation préalable du MOF requise' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Taiwan' AND st.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'fr', 'Transmis à la plateforme du MOF dans un délai de 7 jours (B2B) ou 2 jours (B2C)' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Taiwan' AND st.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'fr', 'Le MOF rapproche les factures transmises des déclarations de TVA déposées' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Taiwan' AND st.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Qui est concerné, et depuis quand', '[["Entités nationales enregistrées à la taxe professionnelle", "Couvertes depuis le 1er janvier 2021, B2B et B2C"], ["Fournisseurs étrangers de services numériques (au-delà du seuil)", "Couverts pour la TVA/eGUI transfrontalière depuis le 1er mai 2017"], ["Vendeurs transfrontaliers via Peppol", "Volontaire depuis le 22 septembre 2025 -- pas une obligation"]]', 'L''adoption du statut d''Autorité Peppol en 2025 est explicitement volontaire -- elle ajoute une option d''échange international au mandat national existant plutôt que de le remplacer ou d''élargir le périmètre des entités concernées.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Taiwan' AND cd.section = 'scope_transmission' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Contexte transfrontalier : adoption de Peppol', '[["Autorité", "Digital Industry Agency (sous le ministère des Affaires numériques)"], ["Adopté", "22 septembre 2025"], ["Statut", "Volontaire -- les spécifications Peppol localisées sont encore en développement"], ["Membres du réseau cités", "Australie, Japon, Malaisie, Nouvelle-Zélande, Singapour, Royaume-Uni"]]', 'Les six membres du réseau Peppol cités sont des juridictions suivies séparément dans ce suivi de conformité -- utile à vérifier si vous échangez déjà des factures électroniques avec l''un d''eux.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Taiwan' AND cd.section = 'scope_transmission' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '💰 1 500-15 000 TWD pour transmission tardive ou inexacte', NULL, NULL, 'L''amendement à la loi sur la taxe professionnelle publié le 3 septembre 2024 a fixé des amendes de 1 500 à 15 000 TWD pour non-respect du délai de transmission de 7 jours (B2B) ou 2 jours (B2C), ou pour transmission de données de facture inexactes. Les sanctions s''aggravent en cas de récidive.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Taiwan' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '📅 Un mandat construit par étapes', NULL, NULL, 'L''histoire de l''eGUI taïwanais s''est déroulée en quatre étapes distinctes : obligations de TVA/eGUI transfrontalières pour les fournisseurs numériques étrangers à partir de 2017, mandat national universel à partir de 2021, délais de transmission et sanctions renforcées à partir de l''amendement BTA de 2024, et le MIG 4.0 devenant le seul format valide à partir de 2026. Chaque étape a modifié une partie différente de l''obligation -- d''abord qui est couvert, puis à quelle vitesse, puis dans quel format -- plutôt qu''une seule date de mandat.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Taiwan' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '🌐 Transfrontalier : Peppol s''ajoute, ce n''est pas un nouveau mandat', NULL, NULL, 'L''adoption par Taïwan du statut d''Autorité Peppol en septembre 2025 est une initiative transfrontalière volontaire supervisée par la Digital Industry Agency -- elle ne modifie pas les obligations nationales d''eGUI et n''introduit aucune nouvelle échéance de conformité. Considérez-la comme une option émergente pour les échanges avec d''autres membres du réseau Peppol (Australie, Japon, Malaisie, Nouvelle-Zélande, Singapour, Royaume-Uni), pas comme une obligation.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Taiwan' AND cd.section = 'penalties_related' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'fr', 'Transmission tardive ou manquante d''un eGUI B2B (au-delà de 7 jours)', '1 500-15 000 TWD', 'S''aggrave en cas de récidive' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Taiwan' AND pr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'fr', 'Transmission tardive ou manquante d''un eGUI B2C (au-delà de 2 jours)', '1 500-15 000 TWD', 'S''aggrave en cas de récidive' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Taiwan' AND pr.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'fr', 'Données de facture transmises inexactes ou erronées', '1 500-15 000 TWD', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Taiwan' AND pr.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Vérifiez que vous êtes concerné -- pratiquement toute entité enregistrée à la taxe professionnelle l''est', 'Les entités nationales B2B et B2C sont couvertes depuis le 1er janvier 2021 ; il n''existe pas d''exemption pour les petites entreprises comme dans certains autres mandats.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Taiwan' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Vérifiez que votre sortie eGUI a migré vers le MIG 4.0', 'Les soumissions au format MIG 3.1/3.2 sont rejetées d''emblée depuis le 1er janvier 2026 -- si votre système de facturation ou ERP n''a pas été mis à niveau, les transmissions échoueront.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Taiwan' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Intégrez le délai de 7 jours / 2 jours dans votre flux de travail', 'Les eGUI B2B doivent parvenir à la plateforme du MOF dans un délai de 7 jours après émission, les B2C dans un délai de 2 jours -- traitez-les comme des délais stricts assortis d''amendes, pas comme des objectifs souples.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Taiwan' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Fournisseurs étrangers de services numériques : vérifiez votre enregistrement à la TVA transfrontalière', 'Si vous vendez des services numériques vers Taïwan au-delà du seuil d''enregistrement, vérifiez que votre enregistrement à la TVA et vos obligations d''émission d''eGUI sont à jour -- ce volet s''applique depuis 2017, distinct du mandat national de 2021.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Taiwan' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Suivez les développements de Peppol si vous échangez avec d''autres membres du réseau', 'L''adoption par Taïwan du statut d''Autorité Peppol en septembre 2025 est volontaire aujourd''hui, mais mérite d''être suivie si vous échangez déjà des factures électroniques avec l''Australie, le Japon, la Malaisie, la Nouvelle-Zélande, Singapour ou le Royaume-Uni.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Taiwan' AND sp.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'fr', 'Ministère des Finances -- Plateforme de facturation électronique' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.name_en = 'Taiwan' AND pt.sort_order = 0;
